import{_ as l,a0 as d,w as s,s as p,I as e,x as o,a1 as n,A as i,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"安卓編年史（33）：安卓 7.0 牛軋糖，Pixel 手機，以及未來 | LCTT x X-CMD","titleTemplate":false,"description":"安卓編年史（33）：安卓 7.0 牛軋糖，Pixel 手機，以及未來 | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓編年史（33）：安卓 7.0 牛軋糖，Pixel 手機，以及未來 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓編年史（33）：安卓 7.0 牛軋糖，Pixel 手機，以及未來 | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/33 The (updated) history of Android","title":"安卓編年史（33）：安卓 7.0 牛軋糖，Pixel 手機，以及未來","tag":"The history of Android","desc":""},"relativePath":"The history of Android/33 The (updated) history of Android.md","filePath":"[post].md"}'),m={name:"The history of Android/33 The (updated) history of Android.md"};function u(g,t,f,x,h,T){const r=d("Link");return s(),p("div",null,[t[31]||(t[31]=e("h1",{id:"安卓編年史-33-安卓-7-0-牛軋糖-pixel-手機-以及未來",tabindex:"-1"},[o("安卓編年史（33）：安卓 7.0 牛軋糖，Pixel 手機，以及未來 "),e("a",{class:"header-anchor",href:"#安卓編年史-33-安卓-7-0-牛軋糖-pixel-手機-以及未來","aria-label":"Permalink to “安卓編年史（33）：安卓 7.0 牛軋糖，Pixel 手機，以及未來”"},"​")],-1)),t[32]||(t[32]=e("h4",{id:"每月安全更新",tabindex:"-1"},[o("每月安全更新 "),e("a",{class:"header-anchor",href:"#每月安全更新","aria-label":"Permalink to “每月安全更新”"},"​")],-1)),e("p",null,[n(r,{href:"https://cdn.arstechnica.net/wp-content/uploads/2016/10/settings-5.jpg"},{default:i(()=>[...t[0]||(t[0]=[e("img",{src:"https://cdn.arstechnica.net/wp-content/uploads/2016/10/settings-5-980x957.jpg",alt:"看看新的“安卓安全補丁程序級別”欄。 "},null,-1)])]),_:1})]),t[33]||(t[33]=a('<p>在棉花糖發佈的幾個月前，安卓的“Stagefright”媒體服務器漏洞被披露給了公眾，這個漏洞允許在舊版本安卓上遠程執行代碼。由於這個漏洞影響到了數十億安卓設備，安卓受到了媒體廣泛的批評。</p><p>谷歌則以開始一項月度安卓安全更新項目作為回應。每個月它都會收集 bug，修復它們，然後推送新代碼給 AOSP 和 Nexus 設備。OEM 廠商——它們已經在更新的泥潭中掙扎（也許是因為不關心）——基本上就是被告知“面對現實”然後跟上步伐。每個其它的主流操作系統有經常的安全更新——這就是成為這麼大的平台的代價。為了協調 OEM 廠商，谷歌讓他們提前一個月可以獲取到更新。30 天之後，發佈安全公告並將更新推送給谷歌設備。</p><p>月度更新項目是在棉花糖發佈的兩個月前開始的，但在這個主要的系統更新中谷歌添加了一欄“安卓安全補丁程序級別”到關於手機界面中。這裏沒有使用晦澀難懂的版本號，就用了日期來表示。這讓任何人都能輕鬆看懂手機系統過時了多久，是個很好的讓動作緩慢的 OEM 廠商羞愧的方式。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/09/text.jpg" alt=""></p><p>文本選擇菜單現在是個浮動工具條，會在你選擇的時候在文本旁邊彈出。這裏也不止是常規的“剪切/複製/粘貼”命令。應用可以在工具欄上放置特殊選項，比如谷歌文檔裏的“添加鏈接”。</p><p>在標準的文本命令之後，一個省略號按鈕會顯示一個二級菜單，應用可以在這裏給文本選擇菜單添加額外的功能。使用新的“文本處理”API，直接給其它應用傳遞文本現在變得非常輕鬆。如果你裝了谷歌翻譯，在這個菜單上會顯示一個“翻譯”選項。谷歌搜索也在這個工具欄裏為谷歌 Now on Tap 添加了一個“助理”選項。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/10/settings-6.jpg" alt=""></p><p>棉花糖添加了一個隱藏的設置，叫做“系統界面調諧器”。這個部分包含了全方位的高級用户特性和試驗性項目。要訪問這個設置，你需要下拉通知中心，按住“設置”按鈕幾秒鐘。設置齒輪會旋轉，然後最終你會看到一條消息顯示系統界面調諧器已解鎖。一旦它被打開，你就可以在系統設置的底部，開發者選項附近找到它了。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/10/settings-7.jpg" alt=""></p><p>在系統界面調諧器的第一部分，用户可以在快速設置面板添加自定義瓷片，這項特性後來被重製成了應用可以使用的 API。此時這項特性還很粗糙，基本就是允許用户在文本框裏輸入一條自定義命令。系統狀態圖標可以單獨打開或關閉，所以如果你真的很討厭知道你已經連接到另外無線網絡，你可以把這個圖標關閉。這裏有一項受歡迎的電源顯示新增特性，可以將電池電量百分比顯示嵌入到電池圖標中。還有個用來截屏的“演示”模式，它會將正常的狀態欄替換成一個假的，乾淨的版本。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/10/easter-egg.jpg" alt=""></p><h3 id="安卓-7-0-牛軋糖-pixel-手機-以及未來" tabindex="-1">安卓 7.0 牛軋糖，Pixel 手機，以及未來 <a class="header-anchor" href="#安卓-7-0-牛軋糖-pixel-手機-以及未來" aria-label="Permalink to “安卓 7.0 牛軋糖，Pixel 手機，以及未來”">​</a></h3>',12)),e("p",null,[n(r,{href:"http://arstechnica.com/gadgets/2016/08/android-7-0-nougat-review-do-more-on-your-gigantic-smartphone/"},{default:i(()=>[...t[1]||(t[1]=[o("安卓 7.0 牛軋糖",-1)])]),_:1}),t[3]||(t[3]=o("和 ",-1)),n(r,{href:"http://arstechnica.com/gadgets/2016/10/google-pixel-review-bland-pricey-but-still-best-android-phone/"},{default:i(()=>[...t[2]||(t[2]=[o("Pixel 手機",-1)])]),_:1}),t[4]||(t[4]=o("幾個月前剛剛發佈，你可以讀讀我們對它們的完整評測。二者都有無數我們還沒看到最終效果的特性和影響，所以我們暫且擱置，等它真正成為“歷史”之後再進行評説。",-1))]),e("p",null,[t[7]||(t[7]=o("牛軋糖為了 Daydream VR 對",-1)),n(r,{href:"http://arstechnica.com/gadgets/2016/08/android-7-0-nougat-review-do-more-on-your-gigantic-smartphone/11/#h1"},{default:i(()=>[...t[5]||(t[5]=[o("圖形和傳感器",-1)])]),_:1}),t[8]||(t[8]=o("做出了很大的改動，Daydream VR 是谷歌即將來臨的智能手機驅動 VR 體驗，",-1)),n(r,{href:"http://arstechnica.com/gadgets/2016/10/daydream-vr-hands-on-googles-dumb-vr-headset-is-actually-very-clever/"},{default:i(()=>[...t[6]||(t[6]=[o("我們已經嘗試過了",-1)])]),_:1}),t[9]||(t[9]=o("但還沒花時間寫下點什麼。從 Chrome OS 借鑑來了新的“無縫升級”功能，系統擁有兩個系統分區，可以在你使用其中一個的時候，對另一個在後台進行靜默升級。考慮到 Pixel 是這個功能的唯一首發設備，並且還沒有收到更新，我們也不確定這個功能是什麼樣子的。",-1))]),t[34]||(t[34]=e("p",null,[e("img",{src:"https://cdn.arstechnica.net/wp-content/uploads/2016/08/Android-N_1-1440x848.jpg",alt:""})],-1)),t[35]||(t[35]=e("p",null,"牛軋糖最有趣的新功能之一是改進的應用框架，它允許改變應用尺寸大小。這讓谷歌可以在手機和平板上實現分屏，在安卓 TV 上實現畫中畫，以及一個神秘的浮動窗口模式。我們已經能夠通過一些軟件技巧來訪問浮動窗口模式，但還沒有看到谷歌在實際產品中使用它。難道它的目標是桌面計算？",-1)),e("p",null,[t[12]||(t[12]=o("安卓和 Chrome OS 則繼續走在共同成長的道路上。安卓應用現在已經能夠在一些 Chromebook 上",-1)),n(r,{href:"http://arstechnica.com/gadgets/2016/05/if-you-want-to-run-android-apps-on-chromebooks-youll-need-a-newer-model/"},{default:i(()=>[...t[10]||(t[10]=[o("運行了",-1)])]),_:1}),t[13]||(t[13]=o("，給了這個“僅 Web”的系統 Play 商店以及一系列的應用生態。有傳言稱 Chrome OS 和安卓未來將會更加緊密結合成“",-1)),n(r,{href:"http://arstechnica.com/gadgets/2016/09/android-chrome-andromeda-merged-os-reportedly-coming-to-the-pixel-3/"},{default:i(()=>[...t[11]||(t[11]=[o("Andromeda",-1)])]),_:1}),t[14]||(t[14]=o("”——一個“Android”和“Chrome”混合而成的詞——它可能是一個融合的 Chrome/安卓系統的代號。",-1))]),t[36]||(t[36]=e("p",null,"我們還沒有看到 Pixel 手機會創造怎樣的歷史。谷歌最近發佈了兩部新旗艦機 Pixel 和 Pixel XL，加入了硬件競爭之中。谷歌之前和合作夥伴合作生產聯名的 Nexus 手機，但 Pixel 產品線用的是“Google”品牌。谷歌聲明這是一個完全的硬件 OEM，HTC 是合同製造商，就類似蘋果把富士康作為合同製造商那樣。",-1)),t[37]||(t[37]=e("p",null,"擁有自己的硬件改變了谷歌製造軟件的方式。谷歌發佈了“谷歌助理”作為未來版的“OK Google”語音命令系統。但助理是 Pixel 的獨佔特性，谷歌沒有把它推送給所有安卓設備。谷歌對界面做了一些改變，一個定製版的“Pixel 啓動器”主屏應用和一套新的系統界面，這些都是 Pixel 獨佔的。我們需要時間來見證未來功能點在“安卓”和“Pixel”之間的平衡。",-1)),e("p",null,[t[16]||(t[16]=o("見證這這些改變，我們可能正處在安卓歷史上最不確定的點上。但在安卓最近的 2016 年 10 月活動前，安卓、Chrome OS以及谷歌 Play 的 SVP ",-1)),n(r,{href:"http://arstechnica.com/gadgets/2016/10/chatting-with-googles-hiroshi-lockheimer-about-pixel-android-oems-and-more/"},{default:i(()=>[...t[15]||(t[15]=[o("Hiroshi Lockheimer",-1)])]),_:1}),t[17]||(t[17]=o(" 説，他相信我們將來都會動情回顧這些最新的安卓更新。Lockheimer 是現在谷歌事實上的軟件統治者，他認為最新的更新會是自安卓八年前亮相以來最有意義的事件。儘管在發佈會後他沒有對這個觀點進行詳細闡述，但事實表明明年這時候我們_可能_都不會討論安卓了——它可能已經是一個安卓/Chrome OS 結合體了！正如 2008 年以來那樣，安卓歷史的下一篇章一定會更加有趣。",-1))]),t[38]||(t[38]=e("hr",null,null,-1)),t[39]||(t[39]=e("p",null,"作者簡介：",-1)),t[40]||(t[40]=e("p",null,"Ron 是 Ars Technica 的評論編緝，專注於安卓系統和谷歌產品。他總是在追尋新鮮事物，還喜歡拆解事物看看它們到底是怎麼運作的。",-1)),t[41]||(t[41]=e("hr",null,null,-1)),e("p",null,[t[19]||(t[19]=o("via: ",-1)),n(r,{href:"http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/33/"},{default:i(()=>[...t[18]||(t[18]=[o("http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/33/",-1)])]),_:1})]),e("p",null,[t[23]||(t[23]=o("作者：",-1)),n(r,{href:"http://arstechnica.com/author/ronamadeo"},{default:i(()=>[...t[20]||(t[20]=[o("RON AMADEO",-1)])]),_:1}),t[24]||(t[24]=o(" 譯者：",-1)),n(r,{href:"https://github.com/alim0x"},{default:i(()=>[...t[21]||(t[21]=[o("alim0x",-1)])]),_:1}),t[25]||(t[25]=o(" 校對：",-1)),n(r,{href:"https://github.com/wxy"},{default:i(()=>[...t[22]||(t[22]=[o("wxy",-1)])]),_:1})]),e("p",null,[t[28]||(t[28]=o("本文由 ",-1)),n(r,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[26]||(t[26]=[o("LCTT",-1)])]),_:1}),t[29]||(t[29]=o(" 原創編譯，",-1)),n(r,{href:"https://linux.cn/"},{default:i(()=>[...t[27]||(t[27]=[o("Linux中國",-1)])]),_:1}),t[30]||(t[30]=o(" 榮譽推出",-1))])])}const A=l(m,[["render",u]]);export{C as __pageData,A as default};
